{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "陆沉",
      "role": "protagonist",
      "identity": "无限流资深玩家，世界排名Top3，代号\"回档者\"",
      "traits": ["沉稳寡言", "战力天花板", "深情偏执", "记忆力超强"],
      "overt_motivation": "带身边的\"新人\"通关所有副本，护她周全",
      "covert_motivation": "寻找三年前死在S级副本里的女友苏晓，弥补当年没能保护好她的遗憾",
      "secret_fear": "再次失去苏晓，确认身边的她只是自己臆想出来的幻影",
      "misperception_of_other": "最初以为苏晓是系统生成的新手引导NPC",
      "hidden_connection": "苏晓是他三年来的强烈执念具象化的数据幻影，也是他现实里相恋五年的女朋友"
    },
    {
      "name": "苏晓",
      "role": "deuteragonist",
      "identity": "无限流\"新人玩家\"/陆沉执念生成的数据幻影",
      "traits": ["软萌乐观", "轻度路痴", "观察力敏锐", "共情力强"],
      "overt_motivation": "跟着身边的强力\"NPC\"通关副本，努力活下去",
      "covert_motivation": "潜意识里寻找缺失的记忆，确认自己对陆沉的好感并非系统设定",
      "secret_fear": "发现自己根本没有现实身份，只是别人记忆里的投影",
      "misperception_of_other": "以为陆沉是系统分配给新人的资深引导NPC",
      "hidden_connection": "三年前和陆沉一起进入无限流世界，为了救陆沉死在S级副本\"深海实验室\"中，账号注销"
    }
  ],
  "supporting_characters": [
    {
      "name": "主神",
      "function": "反转点",
      "identity": "无限流世界的规则管理者",
      "description": "最初是冰冷的规则执行者，被陆沉三年的执念和两人双向的爱意打动，最终成为苏晓复活的关键助力"
    }
  ],
  "relationship_dynamics": "两人绑定特殊的\"复活点共连\"机制，一人死亡另一人立刻强制读档回到副本初始点；互相误以为对方是NPC，在通关副本的过程中双向暗恋，感情逐渐升温；陆沉先发现苏晓的幻影身份，选择隐瞒并拼尽所有守护她，最终两人的爱意打破系统数据屏障，实现真正的双向奔赴。"
}"}

{"path": "outline.json", "content": "{
  "act_one": {
    "description": "第一幕（约7500字，占总篇幅25%）：建立无限流世界观，引入两位主角，展示复活点绑定机制，两人互相误以为对方是NPC，在通关前三个副本的过程中暗生情愫，陆沉偶然发现苏晓的注销ID，核心冲突正式揭开。",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "新手副本的奇怪NPC",
        "core_event": "资深玩家陆沉进入F级新手副本\"校园怪谈\"，遇到蹲在走廊哭的苏晓，误以为她是系统生成的新手引导NPC，意外触发\"复活点共连\"机制，一人死亡另一人立刻读档。",
        "emotional_tone": "轻松、好奇、略带疑惑",
        "key_scenes": ["副本开场，陆沉熟练躲避厕所女鬼的攻击", "转角遇到抱着书包蹲在地上哭的苏晓", "系统弹窗提示：[复活点绑定成功，绑定对象：玩家苏晓]", "陆沉误以为是系统BUG，把苏晓当成NPC"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "三次读档的天花板带飞",
        "core_event": "苏晓三次因为误碰禁忌、走错路、被怪物追击死亡，陆沉三次读档重来，每次都提前规避所有危险，带苏晓零伤亡通关副本，苏晓对这个\"全能NPC\"产生好感。",
        "emotional_tone": "甜爽、暧昧、轻松",
        "key_scenes": ["苏晓误拿了禁止触碰的诅咒娃娃死亡，陆沉第一次读档", "苏晓迷路走到怪物刷新点死亡，陆沉第二次读档", "陆沉提前清光所有怪物，把通关道具直接放到苏晓手里", "副本结算，苏晓对着陆沉的背影犯花痴"]
      },
      {
        "chapter_number": 3,
        "chapter_title": "一模一样的喜好",
        "core_event": "两人回到无限流休息空间，陆沉发现苏晓的饮食习惯、小动作、喜欢的东西都和三年前死去的女友一模一样，苏晓也发现陆沉的休息空间和自己记忆里的家布局完全一致，两人都以为是系统安排的巧合。",
        "emotional_tone": "暧昧、疑惑、微甜",
        "key_scenes": ["苏晓顺手把陆沉不吃的香菜挑出来，动作自然得像做了几百次", "陆沉给苏晓买草莓蛋糕，刚好是她最喜欢的口味", "系统发布下一个副本任务：C级副本\"古堡惊魂\""]
      }
    ],
    "turning_point": "通关第三个副本后，陆沉无意中点开苏晓的资料面板，看到ID下方隐藏的灰色小字：[已注销玩家，注销时间：2023年10月15日]——正是苏晓当年死亡的日期。"
  },
  "act_two": {
    "description": "第二幕（约15000字，占总篇幅50%）：陆沉隐瞒苏晓的身份，带她通关第四到第七个副本，双向暗恋的张力拉满，陆沉收集复活苏晓需要的S级道具，和主神谈判，第八个副本开启，正是三年前苏晓死亡的S级副本。",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "灰色的ID",
        "core_event": "陆沉确认苏晓是自己的执念生成的幻影，没有揭穿她，反而更加小心翼翼地保护她，苏晓以为自己刷满了NPC好感度，暗自开心，两人进入第四个副本\"末日丧尸城\"。",
        "emotional_tone": "微虐、甜宠、略带压抑",
        "key_scenes": ["陆沉看着苏晓的灰色ID，在无人的角落红了眼眶", "陆沉把唯一的防护服给苏晓，自己扛着丧尸攻击", "苏晓给受伤的陆沉包扎，忍不住偷偷亲了他的侧脸"]
      },
      {
        "chapter_number": 5,
        "chapter_title": "七个副本的守护",
        "core_event": "陆沉带苏晓连续通关古堡惊魂、精神病院、雪山迷踪三个副本，每次都把所有危险挡在她前面，苏晓彻底爱上了这个沉默的\"NPC\"，陆沉也集齐了复活苏晓需要的三个S级道具：回溯时钟、灵魂碎片、存在证明。",
        "emotional_tone": "甜爽、暧昧拉满、感动",
        "key_scenes": ["古堡副本里苏晓为陆沉挡了诅咒，陆沉第一次慌得声音发抖", "陆沉为了拿灵魂碎片，硬扛了副本BOSS三次全力攻击", "苏晓在雪地里给陆沉暖手，两人差点接吻"]
      },
      {
        "chapter_number": 6,
        "chapter_title": "主神的警告",
        "core_event": "陆沉尝试用道具恢复苏晓的账号，被主神发现，主神警告他幻影没有存在的权限，要求他删除苏晓，否则抹杀他的账号，陆沉拒绝，提出用自己所有的积分、权限、甚至一半的灵魂数据换苏晓复活的机会。",
        "emotional_tone": "紧张、感动、高燃",
        "key_scenes": ["主神的红色警告弹窗覆盖了整个休息空间", "陆沉把自己的玩家账号权限全部摆到谈判桌上", "主神提出条件：需要苏晓自己产生明确的\"我要存在\"的意志"]
      }
    ],
    "turning_point": "第八个副本强制开启，正是三年前苏晓死亡的S级副本\"深海实验室\"，苏晓一进入副本就开始闪回当年的记忆。"
  },
  "act_three": {
    "description": "第三幕（约7500字，占总篇幅25%）：高潮+结局，苏晓在副本里恢复全部记忆，确认自己对陆沉的爱意，两人的意志打破系统规则，苏晓真正复活，一起通关副本，回到现实世界HE。",
    "key_chapters": [
      {
        "chapter_number": 7,
        "chapter_title": "深海实验室的记忆",
        "core_event": "两人在深海实验室里推进剧情，苏晓不断闪回三年前的画面，看到自己为了救陆沉被怪物刺穿身体的场景，最终在实验室深处看到了自己当年的尸体，意识到自己只是陆沉的执念幻影，崩溃大哭。",
        "emotional_tone": "虐心、压抑、高潮前的铺垫",
        "key_scenes": ["苏晓看到实验室编号，记忆开始闪回", "苏晓想起自己和陆沉是现实里的情侣，一起进入无限流", "苏晓看到自己的尸体，终于明白自己不是真实存在的"]
      },
      {
        "chapter_number": 8,
        "chapter_title": "我想留下来陪你",
        "core_event": "陆沉坦白自己早就知道她的身份，告诉她哪怕她是幻影，他也愿意永远留在无限流里陪她，苏晓也坦白自己早就喜欢上了他，强烈的想要存在的意志触发了复活程序，她的ID从灰色变成了彩色。",
        "emotional_tone": "感动、高燃、高潮",
        "key_scenes": ["陆沉抱住崩溃的苏晓，坦白所有真相", "两人双向告白，三年的思念和爱意爆发", "系统数据剧烈波动，主神宣布复活程序启动"]
      },
      {
        "chapter_number": 9,
        "chapter_title": "现实里的重逢",
        "core_event": "苏晓成功复活，两人合力打败了当年杀死苏晓的BOSS，一起申请注销无限流账号，回到现实世界，陆沉在医院醒来，看到床边刚醒过来的苏晓，两人相拥而泣，再也不分开。",
        "emotional_tone": "甜蜜、治愈、HE",
        "key_scenes": ["两人联手打败深海怪物，副本通关", "注销账号的白光笼罩两人，回到现实", "医院病房里，苏晓笑着伸手摸陆沉的脸，说\"我回来了\""]
      }
    ]
  }
